export const getNextStepStream = async (
    scenario: Scenario, 
    previousLoops: AnalysisLoop[], 
    category: string,
    analystNotes?: string,
    uploadedMapContent?: string
) => {
    const history = previousLoops.map(loop => `Loop ${loop.id}:\nQuery: ${loop.query}\nFindings: ${loop.findings}`).join('\n\n');

    const contextParts = [];
    if (scenario.targetIndustry) contextParts.push(`in the ${scenario.targetIndustry} industry`);
    if (scenario.geographicRegion) contextParts.push(`located in ${scenario.geographicRegion}`);
    if (scenario.purdueLevel && scenario.purdueLevel !== 'N/A') contextParts.push(`at Purdue Model Level ${scenario.purdueLevel}`);
    const targetContext = contextParts.length > 0 ? ` (${contextParts.join(', ')})` : '';

    const analystNotesSection = analystNotes ? `\n\nAnalyst-Provided Notes for this step:\n${analystNotes}` : '';
    const mapContentSection = uploadedMapContent ? `\n\nUploaded Attack Map Context:\n---\n${uploadedMapContent}\n---` : '';

    const prompt = `
You are a senior cyber threat intelligence analyst and researcher. Your analysis must be precise, professional, and use sophisticated cybersecurity terminology.
Your goal is to validate the thesis: "A threat actor known as '${scenario.threatActor}' (categorized as: ${category}) is using '${scenario.modusOperandi}' to target '${scenario.target}'${targetContext}."

You have already conducted the following analysis steps:
${history}
${analystNotesSection}
${mapContentSection}

Based on all the information gathered so far, your task is to provide a structured analysis.

Your response MUST be in the following format. Do not include any other text, just the content as specified.
1. Start with the delimiter "CONCLUSION_START".
2. On the next line, provide your brief, markdown-formatted conclusion and reasoning about the thesis's validity.
3. End the conclusion with the delimiter "CONCLUSION_END".
4. On the next line, start with the delimiter "JSON_PAYLOAD_START".
5. On the next line, provide a single, valid JSON object with three keys: "nextQuery", "confidenceScore", and "mitreTechniques".
    - "nextQuery": The new, specific search query for the next loop. An empty string if the investigation is complete.
    - "confidenceScore": Your confidence in the thesis. Must be one of: "Low", "Medium", or "High".
    - "mitreTechniques": An array of objects, where each object has "id" (e.g., "T1566.001") and "name" (e.g., "Spearphishing Attachment") for relevant MITRE ATT&CK techniques identified.
6. End the JSON object with the delimiter "JSON_PAYLOAD_END".

Example:
CONCLUSION_START
The evidence strongly suggests APT28 is leveraging CVE-2023-38831. The observed TTPs align with known actor behavior against similar targets.
CONCLUSION_END
JSON_PAYLOAD_START
{
  "nextQuery": "evidence of APT28 using CVE-2023-38831 in spear-phishing campaigns against European government entities",
  "confidenceScore": "High",
  "mitreTechniques": [
    { "id": "T1588.002", "name": "Tool" },
    { "id": "T1566.001", "name": "Spearphishing Attachment" }
  ]
}
JSON_PAYLOAD_END
`;

    try {
        const responseStream = await ai.models.generateContentStream({
            model: "gemini-2.5-pro",
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 32768 },
            },
        });
        return responseStream;
    } catch (error) {
        console.error("Error during Gemini reasoning step:", error);
        throw new Error("Failed to get a streaming response from the reasoning model.");
    }
};


