const getBreachDataPrompt = (threatActor: string, modusOperandi: string, dataPoint: DataPointType, year: string, scopeQuery: string): string => {
    const yearConstraint = (year && year !== 'all') ? ` specifically for the year ${year}` : '';
    switch (dataPoint) {
        case 'dataLeaksActor':
            return `Find statistics on data leak incidents attributed to the threat actor: '${threatActor}'${yearConstraint}. Focus on the number of incidents or scale of data compromised. Present the key statistics and provide web sources. If no specific numbers are found, provide a qualitative summary.`;
        case 'fbiIncidentsActor':
            return `Search for official FBI reports, press releases, or advisories regarding cyber incidents involving the threat actor: '${threatActor}'${yearConstraint}. Summarize the key findings and provide links to the official sources.`;
        case 'dataLeaksModus':
            return `Find statistics on data leak incidents related to the modus operandi: '${modusOperandi}'${yearConstraint}. Focus on the number of incidents or scale of data compromised. Present the key statistics and provide web sources. If no specific numbers are found, provide a qualitative summary.`;
        case 'fbiIncidentsModus':
            return `Search for official FBI reports, press releases, or advisories regarding cyber incidents involving the modus operandi: '${modusOperandi}'${yearConstraint}. Summarize the key findings and provide links to the official sources.`;
        case 'ctiicIncidents':
            return `Search for official CTIIC (Cyber Threat Intelligence Integration Center) reports or publications mentioning the modus operandi: '${modusOperandi}'${yearConstraint}. Summarize any relevant incident data and provide links to the official sources.`;
        case 'companiesExposed':
            return `List companies that have been publicly identified as victims of cyber attacks involving '${modusOperandi}'${yearConstraint}. For each company, provide its name and the source of this information.`;
        case 'organizationsInScope':
            return `Find the total number of organizations that match the following description: "${scopeQuery}". Focus on official statistics from government or reputable industry sources. Present the single most relevant number and the source.`;
        default:
            return '';
    }
};

