export const extractKeyStatistic = async (
    threatActor: string,
    modusOperandi: string,
    dataPointType: string,
    contextText: string,
    year: string,
    scopeQuery: string
): Promise<string> => {
    const yearConstraint = (year && year !== 'all') ? ` for the year ${year}` : '';

    // Determine the subject of the statistic extraction based on the card title
    let searchSubject: string;
    const lowerCaseTitle = dataPointType.toLowerCase();
    if (lowerCaseTitle.includes('(actor)')) {
        searchSubject = `the cyber threat actor '${threatActor}'`;
    } else if (lowerCaseTitle.includes('(modus)')) {
        searchSubject = `the modus operandi '${modusOperandi}'`;
    } else if (lowerCaseTitle.includes('in scope')) {
        searchSubject = `organizations matching the description "${scopeQuery}"`;
    } else {
        // A generic fallback just in case
        searchSubject = `the subject "${dataPointType}"`;
    }


    const prompt = `You are a data extraction AI. Your task is to analyze the provided text and extract a single, primary numerical statistic related to ${searchSubject}.

Context Text:
"""
${contextText}
"""

Based on the text above, what is the most significant single number for "${dataPointType}"${yearConstraint}?

- Return only a single numerical value as a string (e.g., "150", "2,000").
- If a range is given (e.g., "100-200"), return the higher number ("200").
- If multiple numbers are present, choose the one that represents the primary count (e.g., number of incidents, companies affected, total organizations).
- If no specific, quantifiable number can be confidently extracted, return the exact string "N/A".

Your entire response must be ONLY the number or "N/A". Do not include any explanations, currency symbols, or extra text.`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash",
            contents: prompt,
            config: {
                temperature: 0.0,
            },
        });
        const resultText = response.text.trim();
        if (resultText === "N/A" || /^[0-9,]+$/.test(resultText)) {
            return resultText;
        }
        console.warn(`Statistic extraction returned unexpected format: "${resultText}"`);
        return "N/A";
    } catch (error) {
        console.error(`Error during statistic extraction for ${dataPointType}:`, error);
        return "Error";
    }
};

export const generateThreatLandscape = async (
    orgProfile: string,
    timePeriod: { startDate: string; endDate: string; name: string },
    numTrends: number
): Promise<ThreatLandscapeResult> => {

    const prompt = `
You are a senior cyber threat intelligence analyst preparing a high-level threat landscape report for a client.
Your task is to analyze global cyber threat intelligence from ${timePeriod.startDate} to ${timePeriod.endDate} using your search capabilities.

Client Organization Profile: "${orgProfile}"

Based on your analysis of publicly available information, identify the top ${numTrends} most significant cyber threat trends during this period.
For each trend, you must provide:
1.  A clear title for the trend.
2.  A "Global Impact" summary, explaining how this trend is affecting organizations worldwide.
3.  An "Organizational Impact" summary, specifically analyzing the potential risks and implications for the client's organization as described above.
4.  A list of relevant MITRE ATT&CK techniques associated with the trend (id and name).
5.  A list of web sources (uri and title) that substantiate your findings for this trend.

Your response MUST be a single, valid JSON object. The JSON should have a 'reportTitle' key and a 'trends' key which is an array of trend objects.
Wrap the entire JSON object in a markdown code block. For example:
\`\`\`json
{
  "reportTitle": "Cyber Threat Landscape: ${timePeriod.name}",
  "trends": [
    {
      "trendTitle": "...",
      "globalImpact": "...",
      "organizationalImpact": "...",
      "mitreTechniques": [{ "id": "Txxxx", "name": "..." }],
      "sources": [{ "uri": "...", "title": "..." }]
    }
  ]
}
\`\`\`
`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-pro",
            contents: prompt,
            config: {
                tools: [{ googleSearch: {} }],
                thinkingConfig: { thinkingBudget: 32768 },
            },
        });

        const textResponse = response.text.trim();

        try {
            // Extract JSON from markdown code block
            const jsonMatch = textResponse.match(/```json([\s\S]*?)```/);

            let jsonString: string;

            if (jsonMatch && jsonMatch[1]) {
                jsonString = jsonMatch[1];
            } else {
                console.warn("Model did not wrap JSON in a markdown block. Attempting to parse the whole response.");
                jsonString = textResponse;
            }

            const jsonResult = JSON.parse(jsonString);

            // --- SOURCE VERIFICATION ---
            // Filter sources against the actual grounding chunks from Google Search to prevent broken links/hallucinations.
            if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
                const chunks = response.candidates[0].groundingMetadata.groundingChunks;
                // Create a set of valid URIs from the metadata
                const validLinkSet = new Set(chunks.map((c: any) => c.web?.uri).filter((u: any) => u));

                // Helper to normalize URLs for comparison (remove trailing slashes)
                const normalizeUrl = (url: string) => url.trim().replace(/\/$/, '');

                if (jsonResult.trends && Array.isArray(jsonResult.trends)) {
                    jsonResult.trends.forEach((trend: any) => {
                        if (trend.sources && Array.isArray(trend.sources)) {
                            trend.sources = trend.sources.filter((s: any) => {
                                if (!s.uri) return false;
                                const normalizedSource = normalizeUrl(s.uri);
                                // Check for exact match or normalized match
                                for (const validUri of validLinkSet) {
                                    if (normalizeUrl(validUri) === normalizedSource) {
                                        return true;
                                    }
                                }
                                return false;
                            });
                        }
                    });
                }
            }

            return jsonResult;
        } catch(parseError) {
            console.error("Failed to parse JSON. Raw model response:", textResponse);
            throw new Error("Failed to parse the threat landscape report from the model. The response was not valid JSON.");
        }
    } catch (apiError) {
        console.error("Error during threat landscape generation API call:", apiError);
        throw new Error("Failed to generate the threat landscape report from the model.");
    }
};

