export const validateThreatTrend = async (
    trendTitle: string,
    trendDetails: string,
    sources: Source[]
): Promise<{ confidenceScore: 'Low' | 'Medium' | 'High'; validationSummary: string }> => {
    const sourcesString = sources.map(s => `- [${s.title}](${s.uri})`).join('\n');
    if (sources.length === 0) {
        return {
            confidenceScore: 'Low',
            validationSummary: 'No sources were provided for validation.'
        };
    }

    const prompt = `
You are a CTI validation agent. Your task is to analyze a generated cyber threat trend and its sources to determine its credibility.

Threat Trend Title: "${trendTitle}"
Trend Details: "${trendDetails}"
Sources:
${sourcesString}

Based on the provided sources, perform the following analysis:
1.  **Source Credibility**: Assess the reputation of the sources. Are they well-known cybersecurity news outlets, official advisories, vendor reports, or less reliable sources like blogs or forums?
2.  **Corroboration**: Is the information supported by multiple, independent sources? A single source, even a good one, is less reliable than multiple corroborating reports.
3.  **Relevance**: Do the sources directly support the claims made in the trend description?

After your analysis, provide a confidence score and a brief justification.

Your response MUST be a single, valid JSON object with two keys: "confidenceScore" and "validationSummary".
- "confidenceScore": A string, must be one of "Low", "Medium", or "High".
- "validationSummary": A concise, one-sentence explanation for your confidence score. For example: "High confidence due to corroboration across multiple reputable cybersecurity news outlets." or "Low confidence as it relies on a single, unverified blog post."
`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-pro",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        confidenceScore: { type: Type.STRING, enum: ["Low", "Medium", "High"] },
                        validationSummary: { type: Type.STRING },
                    },
                    required: ["confidenceScore", "validationSummary"],
                },
            },
        });

        const textResponse = response.text.trim();
        const jsonResponse = JSON.parse(textResponse);

        if (jsonResponse.confidenceScore && jsonResponse.validationSummary) {
            return jsonResponse;
        } else {
             throw new Error("Invalid JSON structure from validation model.");
        }

    } catch(error) {
        console.error("Error during threat trend validation:", error);
        throw new Error("Failed to validate the threat trend.");
    }
};

