export const generateBooleanQuery = async (naturalLanguageQuery: string): Promise<string> => {
    const prompt = `
You are an expert in creating boolean search queries for a threat intelligence platform.
Convert the following natural language request into a valid boolean query string.
- Use operators like AND, OR, NOT.
- Use parentheses () for grouping.
- Use quotes "" for exact phrases.

Your response MUST be ONLY the query string, with no other text, explanation, or markdown formatting.

Natural Language Request:
"${naturalLanguageQuery}"
`;
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash",
            contents: prompt,
            config: {
                temperature: 0.1,
            },
        });
        const query = response.text.trim();
        // A simple check to remove potential markdown quotes or wrapping quotes
        if ((query.startsWith('`') && query.endsWith('`')) || (query.startsWith('"') && query.endsWith('"'))) {
            return query.substring(1, query.length - 1);
        }
        return query;
    } catch (error) {
        console.error("Error generating boolean query:", error);
        throw new Error("Failed to generate boolean query from natural language.");
    }
};

