export const fetchArchetypeSignals = async (scenario: RiskScenario): Promise<ArchetypeSignalResult> => {
    const prompt = `
You are an Archetype Signal Agent. You have been given the following scenario:
- scenarioId: "${scenario.id}"
- archetype: "${scenario.actor_ids[0]}"
- bucket: "${scenario.bucket}"
- vectors: ["${scenario.vectors.split(',').map(v => v.trim()).join('", "')}"]
- targetProfile: "${scenario.targetProfile}"
- baseYear: ${scenario.baseYear}

Search for public reports from the last 12 months that mention concrete metrics (victim counts, campaign sizes, sectors, attack vectors) relevant to this archetype or its known aliases/successors. Cross-reference with major known campaigns like 'MOVEit Transfer (Clop) 2023' or 'LockBit 3.0' if the archetype matches known associated actors.

Your response MUST be a single, valid JSON object with the following structure:
{
  "scenarioId": "${scenario.id}",
  "signals": [
    {
      "signalId": "<unique UUID>",
      "metric": "<descriptive metric name>",
      "value": <numeric value or string>,
      "unit": "<e.g., 'count', 'ratio', 'usd'>",
      "confidence": "<'low'|'medium'|'high'>",
      "excerpt": "<direct quote or summary of the finding>",
      "citationUrl": "<source URL>"
    }
  ]
}

Provide one entry in the "signals" array per distinct metric. If no trustworthy data is found, return the "signals" array as empty ([]), and add an "explanation" key with a sentence explaining why (e.g., "No recent public reporting with concrete metrics for this archetype.").
Do NOT invent numbers or metrics. Your findings must be based on verifiable public sources.
`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-pro",
            contents: prompt,
            config: {
                tools: [{ googleSearch: {} }],
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        scenarioId: { type: Type.STRING },
                        signals: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    signalId: { type: Type.STRING },
                                    metric: { type: Type.STRING },
                                    // Fix: Type.ANY is not a valid enum member in @google/genai.
                                    // Changed to Type.STRING as it can represent both numbers and strings in JSON.
                                    // The client can parse the string to a number if needed.
                                    value: { type: Type.STRING },
                                    unit: { type: Type.STRING },
                                    confidence: { type: Type.STRING, enum: ['low', 'medium', 'high'] },
                                    excerpt: { type: Type.STRING },
                                    citationUrl: { type: Type.STRING },
                                },
                                required: ['signalId', 'metric', 'value', 'unit', 'confidence', 'excerpt', 'citationUrl']
                            }
                        },
                        explanation: { type: Type.STRING, nullable: true },
                    },
                    required: ['scenarioId', 'signals']
                },
                thinkingConfig: { thinkingBudget: 32768 },
            }
        });

        const textResponse = response.text.trim();
        const jsonResponse = JSON.parse(textResponse);

        // The model might not generate a UUID for signalId, so let's ensure it's unique.
        if (jsonResponse.signals) {
            jsonResponse.signals.forEach((signal: SupplementalSignal) => {
                if (!signal.signalId || !signal.signalId.includes('-')) {
                    signal.signalId = uuidv4();
                }
            });
        }

        return jsonResponse;

    } catch (error) {
        console.error("Error fetching archetype signals:", error);
        throw new Error("Failed to fetch archetype signals from the model.");
    }
};

