import { GoogleGenAI, Type } from "@google/genai";
import { v4 as uuidv4 } from 'uuid';
import type { Scenario, AnalysisLoop, Source, MitreTechnique, DataPointType, ThreatLandscapeResult, ThreatMatrixResult, ThreatRadarResult, ChatMessage, Memorandum, ThreatRadarPoint, ThreatMatrixPreview, ThreatLandscapeTrend, IntelligenceDashboardData, AttemptCalculationResult, RiskScenario, SupplementalSignal, ArchetypeSignalResult, SuccessCalculationResult } from '../types';

// Per coding guidelines, API_KEY is assumed to be present in process.env and fallbacks or checks are not to be used.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const parseSources = (groundMetadata: any): Source[] => {
    if (!groundMetadata?.groundingChunks) {
        return [];
    }
    const sources: Source[] = [];
    for (const chunk of groundMetadata.groundingChunks) {
        if (chunk.web) {
            sources.push({
                uri: chunk.web.uri,
                title: chunk.web.title || 'Untitled Source',
            });
        }
    }
    return sources;
};

export const categorizeThreatActor = async (actorName: string): Promise<{ category: string; justification: string }> => {
    const prompt = `
You are a senior cyber threat intelligence analyst. Your analysis must be precise and professional. Your task is to categorize the provided threat actor.

Threat Actor: "${actorName}"

Categorize this actor into one of the following three categories:
1. Non-advanced Cyber Criminal
2. Advanced Cyber Criminal (Nation-state support)
3. Nation-state Actor

Provide a brief justification for your choice.

Your response MUST be a valid JSON object with two keys: "category" and "justification".
- "category": A string containing one of the three categories listed above.
- "justification": A concise explanation for the categorization.
`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        category: { type: Type.STRING },
                        justification: { type: Type.STRING },
                    },
                    required: ["category", "justification"],
                },
            },
        });

        const textResponse = response.text.trim();
        const jsonResponse = JSON.parse(textResponse);

        if (jsonResponse.category && jsonResponse.justification) {
            return {
                category: jsonResponse.category,
                justification: jsonResponse.justification,
            };
        } else {
            throw new Error("Invalid JSON structure from categorization model.");
        }
    } catch (error) {
        console.error("Error during threat actor categorization:", error);
        throw new Error("Failed to categorize the threat actor.");
    }
};

