        console.error("Error generating yearly attempts narrative:", error);
        return {
            summary: "Error: Failed to generate a narrative for the calculation.",
            justification: "The narrative generation model returned an error. Please refer to the deterministic ledger for calculation details.",
        };
    }
};

export const extractVectorsFromText = async (textContent: string): Promise<string[]> => {
    if (!textContent.trim()) {
        return [];
    }

    const prompt = `
You are a Cyber Threat Intelligence Analyst AI. Your task is to extract attack vectors from the provided text.
The text is from a supporting document describing a cyber attack scenario or threat actor.

Text to analyze:
---
${textContent}
---

Identify the specific attack vectors mentioned (e.g., "phishing", "RDP", "malware dropper", "CVE-2023-1234").
Return your findings as a single, valid JSON array of strings. Each string in the array should be a distinct vector.
If no vectors are clearly identified, return an empty array.

Example response:
["phishing", "malicious documents", "RDP brute-force"]
`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.STRING,
                    },
                },
            },
        });

        const textResponse = response.text.trim();
        const jsonResponse = JSON.parse(textResponse);

        if (Array.isArray(jsonResponse)) {
            return jsonResponse.filter(item => typeof item === 'string');
        }
        return [];
    } catch (error) {
        console.error("Error during vector extraction:", error);
        return []; // Return empty array on failure
    }
};

