export const getNextStepStream = async (
    scenario: Scenario,
    previousLoops: AnalysisLoop[],
    categorization: string,
    analystNotes?: string,
    contextContent?: string
) => {
    const systemInstruction = `You are an expert Cyber Threat Intelligence Analyst (Human-in-the-Loop AI). Your goal is to research a specific threat scenario deeply and methodically.

Scenario:
- Threat Actor: ${scenario.threatActor} (${categorization})
- Modus Operandi: ${scenario.modusOperandi}
- Target: ${scenario.target}
- Industry: ${scenario.targetIndustry || 'N/A'}
- Region: ${scenario.geographicRegion || 'N/A'}

You are in a loop of analysis. Review the findings from previous steps and determine the next best step.

Previous Analysis Steps:
${previousLoops.map(loop => `Loop ${loop.id} Query: ${loop.query}\nLoop ${loop.id} Findings: ${loop.findings.substring(0, 500)}...`).join('\n\n')}

${analystNotes ? `\nIMPORTANT ANALYST NOTES: ${analystNotes}\n` : ''}
${contextContent ? `\nUPLOADED CONTEXT: ${contextContent.substring(0, 1000)}...\n` : ''}

Instructions:
1. Synthesize the findings so far.
2. Identify intelligence gaps (e.g., specific TTPs, infrastructure, attribution evidence, recent campaigns).
3. Formulate the next specific search query to close a gap.
4. If you have sufficient information to conclude the analysis (5+ high quality findings or definitive evidence), set "nextQuery" to null or empty string.
5. Assign a confidence score (Low, Medium, High) to the current assessment.
6. Identify relevant MITRE ATT&CK techniques found so far.

Output Format:
First, stream your reasoning and synthesis in plain text.
Then, output specific markers "CONCLUSION_START" and "CONCLUSION_END" wrapping your summary.
Finally, output markers "JSON_PAYLOAD_START" and "JSON_PAYLOAD_END" wrapping a valid JSON object with:
- "nextQuery": string (or null if finished)
- "confidenceScore": string (Low, Medium, High)
- "mitreTechniques": array of objects { "id": string, "name": string }
`;

    try {
        return await ai.models.generateContentStream({
            model: "gemini-3-pro-preview",
            contents: "Analyze the current state and determine the next step.",
            config: {
                systemInstruction: systemInstruction,
            }
        });
    } catch (error) {
        console.error("Error generating next step:", error);
        throw error;
    }
};

