export const getBreachDataPoint = async (
    threatActor: string, 
    modusOperandi: string, 
    dataPointId: DataPointType,
    year: string,
    scope: string
): Promise<{ text: string, sources: Source[] }> => {
    let query = "";
    switch(dataPointId) {
        case 'dataLeaksActor': query = `"${threatActor}" data leaks victims count statistics ${year === 'all' ? '' : year}`; break;
        case 'fbiIncidentsActor': query = `site:fbi.gov "${threatActor}" incidents report`; break;
        case 'dataLeaksModus': query = `"${modusOperandi}" data leaks statistics ${year === 'all' ? '' : year}`; break;
        case 'fbiIncidentsModus': query = `site:fbi.gov "${modusOperandi}" incidents statistics`; break;
        case 'ctiicIncidents': query = `CTIIC report "${modusOperandi}" cyber incidents`; break;
        case 'companiesExposed': query = `companies victim of "${modusOperandi}" ${year === 'all' ? '' : year} list`; break;
        case 'organizationsInScope': query = `number of ${scope}`; break;
    }

    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: `Find precise data/statistics for: ${query}. Summarize the key findings in 2-3 sentences.`,
            config: {
                tools: [{ googleSearch: {} }],
            },
        });

        return {
            text: response.text || "No data found.",
            sources: parseSources(response.candidates?.[0]?.groundingMetadata),
        };
    } catch (error) {
        console.error(`Error fetching breach data for ${dataPointId}:`, error);
        throw error;
    }
};

