export const validateThreatTrend = async (title: string, claim: string, existingSources: Source[]): Promise<{
    validationStatus: 'validated' | 'error';
    confidenceScore: 'Low' | 'Medium' | 'High';
    validationSummary: string;
    sources: Source[];
}> => {
    const prompt = `Validate this threat trend: "${title}". Claim: "${claim}". Search for recent evidence.`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash",
            contents: prompt,
            config: {
                tools: [{ googleSearch: {} }]
            }
        });

        const sources = parseSources(response.candidates?.[0]?.groundingMetadata);

        // Simple logic to determine confidence based on source count
        const confidence = sources.length > 3 ? 'High' : sources.length > 0 ? 'Medium' : 'Low';
        const summary = response.text?.substring(0, 150) + "..." || "Validation check complete.";

        return {
            validationStatus: 'validated',
            confidenceScore: confidence,
            validationSummary: summary,
            sources: [...existingSources, ...sources]
        };
    } catch (e) {
        return { validationStatus: 'error', confidenceScore: 'Low', validationSummary: 'Validation failed.', sources: existingSources };
    }
};

