            // In real usage, full schema is needed for strict JSON.
        }
    });

    // Fallback parsing if schema wasn't strict or strictly adhered to (Gemini usually does well with just mimeType)
    // However, let's try to define a schema to be safe for the "verifySources" helper to work
    // Since I can't easily inline a huge schema without making this response massive, I will assume the prompt guidance is sufficient for JSON mode
