export const InlineProjectionChart: React.FC<{ threat: ThreatRadarPoint }> = ({ threat }) => {
    const width = 300;
    const height = 120;
    const margin = { top: 20, right: 20, bottom: 30, left: 30 };

    const plotData = useMemo(() => [
        { quarter: 'Current', motivation: threat.motivation, resources: threat.resources },
        ...threat.quarterlyData
    ], [threat]);

    const xScale = (index: number) => {
        if (plotData.length <= 1) return margin.left;
        return margin.left + (index / (plotData.length - 1)) * (width - margin.left - margin.right);
    };
    const yScale = (value: number) => height - margin.bottom - ((value - 1) / 9) * (height - margin.top - margin.bottom);

    const motivationPath = plotData.map((d, i) => `${i === 0 ? 'M' : 'L'} ${xScale(i)} ${yScale(d.motivation)}`).join(' ');
    const resourcesPath = plotData.map((d, i) => `${i === 0 ? 'M' : 'L'} ${xScale(i)} ${yScale(d.resources)}`).join(' ');

    return (
        <div className="bg-surface/50 p-2 rounded-md">
            <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-auto font-sans">
                {/* Y-axis grid lines and labels */}
                {[1, 5, 10].map(val => (
                    <g key={val} className="text-[8px] fill-text-secondary">
                        <line x1={margin.left} y1={yScale(val)} x2={width - margin.right} y2={yScale(val)} stroke="currentColor" strokeOpacity="0.2" strokeWidth="1" />
                        <text x={margin.left - 4} y={yScale(val)} dy="0.32em" textAnchor="end">{val}</text>
                    </g>
                ))}

                {/* X-axis labels */}
                {plotData.map((d, i) => (
                    <text key={d.quarter} x={xScale(i)} y={height - margin.bottom + 10} textAnchor="middle" className="text-[8px] fill-text-secondary">{d.quarter}</text>
                ))}

                {/* Lines and points */}
                <path d={motivationPath} fill="none" stroke="var(--color-accent-pro)" strokeWidth="1.5" />
                <path d={resourcesPath} fill="none" stroke="var(--color-accent-primary)" strokeWidth="1.5" />
                {plotData.map((d, i) => (
                    <g key={`points-${i}`}>
                        <circle cx={xScale(i)} cy={yScale(d.motivation)} r="2.5" fill="var(--color-accent-pro)" />
                        <circle cx={xScale(i)} cy={yScale(d.resources)} r="2.5" fill="var(--color-accent-primary)" />
                    </g>
                ))}

                {/* Legend */}
                <g transform={`translate(${margin.left}, 0)`}>
                    <rect x="0" y="0" width="8" height="8" fill="var(--color-accent-pro)" rx="2"/>
                    <text x="12" y="7" className="text-[9px] fill-text-primary">Motivation</text>
                    <rect x="70" y="0" width="8" height="8" fill="var(--color-accent-primary)" rx="2"/>
                    <text x="82" y="7" className="text-[9px] fill-text-primary">Resources</text>
                </g>
            </svg>
        </div>
    );
};

const renderImpactContent = (content: string | string[]) => {
    let lines: string[] = [];

    if (Array.isArray(content)) {
        lines = content.filter(line => typeof line === 'string' && line.trim().length > 0);
    } else if (typeof content === 'string') {
        lines = content.split('\n').filter(line => line.trim().length > 0);
    } else {
        return <p className="text-sm text-text-secondary">No impact data available.</p>;
    }

    // Heuristic: If it looks like a list (starts with markers like -, *, 1.) OR has multiple lines, treat as list.
    const hasMarkers = lines.some(line => /^[*-•]|\d+\./.test(line.trim()));

    // Ensure we render a list if we have multiple points, even if they don't have markers (we'll assume they are points)
    if (lines.length > 1 || hasMarkers) {
        return (
            <ul className="list-disc pl-5 space-y-1.5">
                {lines.map((line, i) => {
                    // Clean the line of existing markers to avoid double bullets
                    const cleanLine = line.replace(/^[*-•]\s*/, '').replace(/^\d+\.\s*/, '').trim();
                    return (
                        <li key={i} className="text-sm text-text-secondary leading-relaxed">
                            {cleanLine}
                        </li>
                    );
                })}
            </ul>
        );
    }
    // Fallback for single line content without markers
    return <p className="text-sm text-text-secondary whitespace-pre-wrap leading-relaxed">{lines[0] || content}</p>;
};

