    const handleSaveReport = () => {
        if (!topTrendsResult && !matrixResult) return;

        const reportToSave: SavedThreatLandscape = {
            id: uuidv4(),
            timestamp: Date.now(),
            report: (topTrendsResult || matrixResult)!,
