// --- Helper for verifying sources ---
const verifySources = (jsonResult: any, response: any) => {
    if (!jsonResult) return {};

    // Ensure arrays and required strings exist regardless of grounding
    if (jsonResult.trends && Array.isArray(jsonResult.trends)) {
        jsonResult.trends.forEach((trend: any) => {
            if (!trend.sources) trend.sources = [];
            if (!trend.mitreTechniques) trend.mitreTechniques = [];
            if (!trend.globalImpact) trend.globalImpact = "No global impact data available.";
            if (!trend.organizationalImpact) trend.organizationalImpact = "No organizational impact data available.";
        });
    }

    if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
        const chunks = response.candidates[0].groundingMetadata.groundingChunks;
        const validLinkSet = new Set(
            chunks.map((c: any) => c.web?.uri).filter((u: any): u is string => typeof u === 'string')
        );
        const normalizeUrl = (url: string) => url ? url.trim().replace(/\/$/, '') : '';

        if (jsonResult.trends && Array.isArray(jsonResult.trends)) {
            jsonResult.trends.forEach((trend: any) => {
                if (trend.sources && Array.isArray(trend.sources)) {
                    trend.sources = trend.sources.filter((s: any) => {
                        if (!s.uri) return false;
                        const normalizedSource = normalizeUrl(s.uri as string);
                        for (const validUri of validLinkSet) {
                            if (normalizeUrl(validUri as string) === normalizedSource) return true;
                        }
                        return false;
                    });
                }
            });
        }
        // Similar logic for matrix quadrants if needed
        ['nationStateTech', 'nationStateGeopolitical', 'criminalTech', 'criminalGeopolitical'].forEach(key => {
            if (jsonResult[key]) {
                if (!jsonResult[key].sources) jsonResult[key].sources = [];

                if (jsonResult[key].sources) {
                     jsonResult[key].sources = jsonResult[key].sources.filter((s: any) => {
                            if (!s.uri) return false;
                            const normalizedSource = normalizeUrl(s.uri as string);
                            for (const validUri of validLinkSet) {
                                if (normalizeUrl(validUri as string) === normalizedSource) return true;
                            }
                            return false;
                        });
                }
            }
        });
    }
    return jsonResult;
};

export const generateThreatLandscape = async (orgProfile: string, period: { startDate: string, endDate: string, name: string }, numTrends: number) => {
    const prompt = `Generate a threat landscape report for: ${orgProfile}. Period: ${period.name}. Identify top ${numTrends} trends.
    For each trend, provide title, global impact, organizational impact, MITRE techniques, and sources.`;

    // Increased retries for complex generation to handle RPC errors
    const response = await retry(() => ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
            tools: [{ googleSearch: {} }],
            responseMimeType: 'application/json',
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    reportTitle: { type: Type.STRING },
                    trends: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                trendTitle: { type: Type.STRING },
                                globalImpact: { type: Type.STRING },
                                organizationalImpact: { type: Type.STRING },
                                mitreTechniques: { 
                                    type: Type.ARRAY,
                                    items: { type: Type.OBJECT, properties: { id: { type: Type.STRING }, name: { type: Type.STRING } } }
                                },
                                sources: { 
                                    type: Type.ARRAY, 
                                    items: { type: Type.OBJECT, properties: { uri: { type: Type.STRING }, title: { type: Type.STRING } } } 
                                }
                            }
                        }
                    }
                }
            }
        }
    }), 3, 2000) as GenerateContentResponse;

    let result = JSON.parse(response.text || '{}');
    result = verifySources(result, response);
    return result as ThreatLandscapeResult;
};

