export const getNextStepStream = async (
    scenario: Scenario, 
    previousLoops: AnalysisLoop[], 
    category: string, 
    analystNotes: string,
    contextContent: string
) => {
    const historyText = previousLoops.map(l => `Query: ${l.query}\nFindings: ${l.findings}\nConclusion: ${l.conclusion}`).join('\n---\n');

    const prompt = `
    You are a senior CTI analyst.
    Scenario: ${JSON.stringify(scenario)}
    Actor Category: ${category}
    Analyst Notes: ${analystNotes}
    Additional Context: ${contextContent}

    Previous Analysis Steps:
    ${historyText}

    Based on the above, synthesize the findings. If more information is needed, formulate the next search query.
    If the analysis is complete, set "nextQuery" to empty string.

    Output format:
    CONCLUSION_START
    (Your synthesis here)
    CONCLUSION_END
    JSON_PAYLOAD_START
    {
      "nextQuery": "string or empty",
      "confidenceScore": "Low" | "Medium" | "High",
      "mitreTechniques": [ { "id": "string", "name": "string" } ]
    }
    JSON_PAYLOAD_END
    `;

    return await ai.models.generateContentStream({
        model: 'gemini-3-pro-preview',
        contents: prompt
    });
};

