export const generateThreatLandscape = async (orgProfile: string, period: { startDate: string, endDate: string, name: string }, numTrends: number) => {
    const prompt = `Generate a threat landscape report for: ${orgProfile}. Period: ${period.name}. Identify top ${numTrends} trends.
    Structure:
    - reportTitle: A short, descriptive title for the entire report (MAX 10 WORDS).
    - trends: An array of ${numTrends} trends.

    For each trend:
    - trendTitle: Concise title (max 10 words).
    - globalImpact: A short summary paragraph followed by 2-3 key bullet points.
    - organizationalImpact: A short summary paragraph explaining impact on ${orgProfile}, followed by 2-3 key bullet points.
    - mitreTechniques: Max 3 techniques.
    - sources: List of sources.

    CRITICAL: Keep output concise to ensure valid JSON generation. Avoid excessively long descriptions.`;

    return await retry(async () => {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                tools: [{ googleSearch: {} }],
                responseMimeType: 'application/json',
                maxOutputTokens: 4000, // Limit output to prevent huge strings/loops
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        reportTitle: { type: Type.STRING },
                        trends: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    trendTitle: { type: Type.STRING },
                                    globalImpact: { type: Type.STRING },
                                    organizationalImpact: { type: Type.STRING },
                                    mitreTechniques: { 
                                        type: Type.ARRAY,
                                        items: { type: Type.OBJECT, properties: { id: { type: Type.STRING }, name: { type: Type.STRING } } }
                                    },
                                    sources: { 
                                        type: Type.ARRAY, 
                                        items: { type: Type.OBJECT, properties: { uri: { type: Type.STRING }, title: { type: Type.STRING } } } 
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }) as GenerateContentResponse;

        let result = JSON.parse(cleanJson(response.text || '{}'));
        result = verifySources(result, response);
        return result as ThreatLandscapeResult;
    }, 3, 2000); 
};

