                                        ? 'bg-card border-border border-b-transparent text-accent-primary z-10'
                                        : 'bg-surface border-transparent text-text-secondary hover:text-text-primary hover:bg-white/5'
                                }`}
                            >
                                Trend {index + 1}
                            </button>
                        );
                    })}
                </div>
            </header>
            <main className="flex-grow bg-card p-0 overflow-y-auto">
                {result.trends[activeTab] && (
                    <div className="animate-fade-in bg-card min-h-[500px]">
                        <TrendCard 
                            trend={result.trends[activeTab]}
                            trendNumber={activeTab + 1}
