                                        </>
                                    )}
                                </button>
                            )}
                        </div>
                    </div>

                    {landscapeMode === 'event' && (
                        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-fade-in">
                            <div className="lg:col-span-1 bg-card border border-border rounded-lg p-4 h-fit max-h-[600px] flex flex-col">
