                                                            >
                                                                <TrashIcon className="w-4 h-4" />
                                                            </button>
                                                        </div>
                                                    </div>
                                                </li>
                                            ))}
                                        </ul>
                                    ) : (
                                        <div className="flex items-center justify-center h-full text-center text-text-secondary p-4">
                                            <p className="text-sm">No memorandums generated yet. Use the form above to create one.</p>
                                        </div>
                                    )}
                                </div>
                            </div>
                            <div className="lg:col-span-2">
                                {activeMemorandum ? (
                                    <div className="bg-card border border-border rounded-lg shadow-sm p-6 animate-fade-in">
                                        <MemorandumDisplay 
                                            memo={activeMemorandum.memorandum} 
                                            audience={activeMemorandum.targetAudience} 
                                            subject={activeMemorandum.eventDescription}
                                        />
                                    </div>
                                ) : (
                                     <div className="bg-card border-2 border-dashed border-border rounded-lg h-full flex items-center justify-center text-center text-text-secondary p-6">
                                        <p>{savedMemorandums.length > 0 ? 'Select a memorandum from the list to view it.' : 'Your generated memorandum will be displayed here.'}</p>
                                    </div>
                                )}
                            </div>
                        </div>
                    )}

                    {landscapeMode === 'matrix' && matrixResult && (
                        <div className="space-y-8 animate-fade-in">
                            <StructuredMatrixView result={matrixResult} />
                        </div>
                    )}

                    {landscapeMode === 'trends' && reportViewMode === 'overview' && (
                        <div className="space-y-8 animate-fade-in">
                            <div className="grid grid-cols-1 xl:grid-cols-4 gap-8 items-start">
                                {topTrendsResult && (
                                    <div className="xl:col-span-3">
                                        <TopTrendsView
                                            result={topTrendsResult}
                                            orgProfile={orgProfile}
                                            onAcceptUpdate={handleAcceptUpdate}
                                            onRejectUpdate={handleRejectUpdate}
                                        />
                                    </div>
                                )}
                                {topTrendsResult && (
                                    <div className="xl:col-span-1">
                                        <ReportChat
                                            messages={chatHistory}
                                            inputValue={chatInput}
                                            onInputChange={setChatInput}
                                            onSendMessage={handleSendMessage}
                                            isLoading={isChatLoading}
                                        />
                                    </div>
                                )}
                            </div>
                        </div>
                    )}

                    {landscapeMode === 'trends' && reportViewMode === 'reportViewer' && topTrendsResult && (
                        <div className="grid grid-cols-1 xl:grid-cols-2 gap-8 items-start animate-fade-in">
                            <TailoredReportViewer
                                report={topTrendsResult}
                                orgProfile={orgProfile}
                                activeAudience={activeAudienceView}
                                onAudienceChange={setActiveAudienceView}
                                onExit={() => setReportViewMode('overview')}
                                onGenerateMemorandum={handleGenerateMemorandum}
                            />
                             <ReportChat
                                messages={chatHistory}
                                inputValue={chatInput}
                                onInputChange={setChatInput}
                                onSendMessage={handleSendMessage}
                                isLoading={isChatLoading}
                            />
                        </div>
                    )}

                    {(topTrendsResult || matrixResult) && (
                        <div className="flex justify-end pt-4 gap-3">
                            <button 
                                onClick={handleSaveReport} 
                                className="px-4 py-2 bg-surface hover:bg-border text-text-primary font-semibold rounded-lg shadow-sm transition-all duration-300 border border-border flex items-center gap-2"
                            >
                                <CheckIcon className="w-4 h-4" />
                                {saveButtonText}
                            </button>
                            <button onClick={handleCopyToClipboard} className="px-4 py-2 bg-accent-primary hover:opacity-90 text-white font-semibold rounded-lg shadow-sm transition-all duration-300 flex items-center gap-2">
                                <ClipboardIcon className="w-4 h-4" />
                                {isTailoredReportReady ? `Copy Report for ${activeAudienceView}` : copyButtonText}
                            </button>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import type { 
    Scenario, AnalysisLoop, ThreatLandscapeResult, ThreatMatrixResult, 
    ThreatMatrixPreview, ThreatRadarResult, Memorandum, 
    TailoredAnalysis, ChatMessage, SupplementalSignal, 
    ArchetypeSignalResult, IntelligenceDashboardData,
    CyberThreat, CriticalVulnerability, GeopoliticalEvent,
    Source, ThreatLandscapeTrend, ThreatMatrixQuadrant
} from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Robust JSON extractor that handles markdown blocks and balances braces 
// to ignore trailing text (fixing "Unexpected non-whitespace character" errors).
const cleanJson = (text: string) => {
    if (!text) return '{}';

    // 1. Try to find markdown code block first
    const match = text.match(/```json\s*([\s\S]*?)\s*```/);
    if (match) {
        return match[1].trim();
    }

    // 2. Find the first '{'
    const firstBrace = text.indexOf('{');
    if (firstBrace === -1) return text.trim();

    // 3. Balance braces to find the end of the JSON object
    let balance = 0;
    let inString = false;
    let escape = false;
    let end = -1;

    for (let i = firstBrace; i < text.length; i++) {
        const char = text[i];

        if (escape) {
            escape = false;
            continue;
        }

        if (char === '\\') {
            escape = true;
            continue;
        }

        if (char === '"') {
            inString = !inString;
            continue;
        }

        if (!inString) {
            if (char === '{') {
                balance++;
            } else if (char === '}') {
                balance--;
                if (balance === 0) {
                    end = i;
                    break;
                }
            }
        }
    }

    if (end !== -1) {
        return text.substring(firstBrace, end + 1);
    }

    // Fallback: if unbalanced (likely truncated), return from start to raw end 
    // so JSON.parse throws a clear error or we can attempt partial recovery later if needed.
    return text.substring(firstBrace);
};

// Helper for retrying async operations
const retry = async <T>(fn: () => Promise<T>, retries = 3, delay = 1000): Promise<T> => {
    try {
        return await fn();
    } catch (error) {
        if (retries <= 0) throw error;
        console.warn(`Retrying operation... Attempts left: ${retries}. Error: ${error}`);
        await new Promise(resolve => setTimeout(resolve, delay));
        return retry(fn, retries - 1, delay * 2);
    }
};

// --- Helper for verifying sources and ensuring data integrity ---
const verifySources = (jsonResult: any, response: any) => {
    if (!jsonResult) return {};

    // Ensure arrays and required strings exist regardless of grounding
    if (jsonResult.trends && Array.isArray(jsonResult.trends)) {
        jsonResult.trends.forEach((trend: any) => {
            if (!trend.sources) trend.sources = [];
            if (!trend.mitreTechniques) trend.mitreTechniques = [];

            // Fallback for empty strings or malformed "no data" responses
            // We check for "yielded no specific" to catch AI-generated variations like "Analysis yielded no specific..."
            if (!trend.globalImpact || typeof trend.globalImpact !== 'string' || !trend.globalImpact.trim() || trend.globalImpact.toLowerCase().includes('yielded no specific')) {
                trend.globalImpact = "Analysis yielded no specific global impact data.";
            }
            if (!trend.organizationalImpact || typeof trend.organizationalImpact !== 'string' || !trend.organizationalImpact.trim() || trend.organizationalImpact.toLowerCase().includes('yielded no specific')) {
                trend.organizationalImpact = "Analysis yielded no specific organizational impact data.";
            }
        });
    }

    if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
        const chunks = response.candidates[0].groundingMetadata.groundingChunks;
        const validLinkSet = new Set(
            chunks.map((c: any) => c.web?.uri).filter((u: any): u is string => typeof u === 'string')
        );
        const normalizeUrl = (url: string) => url ? url.trim().replace(/\/$/, '') : '';

        if (jsonResult.trends && Array.isArray(jsonResult.trends)) {
            jsonResult.trends.forEach((trend: any) => {
                if (trend.sources && Array.isArray(trend.sources)) {
                    trend.sources = trend.sources.filter((s: any) => {
                        if (!s.uri) return false;
                        const normalizedSource = normalizeUrl(s.uri as string);
                        for (const validUri of validLinkSet) {
                            if (normalizeUrl(validUri as string) === normalizedSource) return true;
                        }
                        return false;
                    });
                }
            });
        }
        // Similar logic for matrix quadrants if needed
        ['nationStateTech', 'nationStateGeopolitical', 'criminalTech', 'criminalGeopolitical'].forEach(key => {
            if (jsonResult[key]) {
                if (!jsonResult[key].sources) jsonResult[key].sources = [];

                if (jsonResult[key].sources) {
                     jsonResult[key].sources = jsonResult[key].sources.filter((s: any) => {
                            if (!s.uri) return false;
                            const normalizedSource = normalizeUrl(s.uri as string);
                            for (const validUri of validLinkSet) {
                                if (normalizeUrl(validUri as string) === normalizedSource) return true;
                            }
                            return false;
                        });
                }
            }
        });
    }
    return jsonResult;
};

