                            <textarea value={eventDescription} onChange={(e) => setEventDescription(e.target.value)} rows={2} placeholder="Describe the specific event to analyze, e.g., 'Suspected Russian cyberattack on German energy infrastructure'..." className={commonInputClass} />
                        </div>
                        <div className="md:col-span-12">
