// Reverted simple renderImpactContent
const renderImpactContent = (content: string) => {
    // Check for empty or error state
    if (!content || content.includes("Analysis yielded no specific")) {
        return <p className="text-sm text-text-secondary italic">Analysis yielded no specific impact data.</p>;
    }

    // Split by newlines to render paragraphs/lists properly
    const lines = content.split('\n').filter(line => line.trim().length > 0);

    return (
        <div className="space-y-2">
            {lines.map((line, idx) => {
                const isBullet = line.trim().startsWith('-') || line.trim().startsWith('•') || line.trim().startsWith('*');
                if (isBullet) {
                    return <li key={idx} className="text-sm text-text-secondary ml-4 list-disc">{line.replace(/^[•*-]\s*/, '')}</li>
                }
                return <p key={idx} className="text-sm text-text-secondary leading-relaxed">{line}</p>
            })}
        </div>
    );
};

