export const generateThreatLandscape = async (orgProfile: string, period: { startDate: string, endDate: string, name: string }, numTrends: number) => {
    // Optimized prompt to reduce token count and prevent truncation
    const prompt = `Generate a threat landscape report for: ${orgProfile}. Period: ${period.name}. Identify top ${numTrends} trends.

    Structure:
    - reportTitle: A descriptive title (max 10 words).
    - trends: An array of ${numTrends} trends.

    For each trend:
    - trendTitle: Title (max 10 words).
    - globalImpact: A CONCISE summary of global impact (max 3 sentences).
    - organizationalImpact: A CONCISE summary of impact on ${orgProfile} (max 3 sentences).
    - mitreTechniques: Max 3 techniques.
    - sources: List of sources used.

    CRITICAL: Output MUST be valid JSON. Ensure strictly escaped strings. Keep text brief to avoid truncation.`;

    return await retry(async () => {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                tools: [{ googleSearch: {} }],
                responseMimeType: 'application/json',
                maxOutputTokens: 8192,
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        reportTitle: { type: Type.STRING },
                        trends: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    trendTitle: { type: Type.STRING },
                                    globalImpact: { type: Type.STRING },
                                    organizationalImpact: { type: Type.STRING },
                                    mitreTechniques: { 
                                        type: Type.ARRAY,
                                        items: { type: Type.OBJECT, properties: { id: { type: Type.STRING }, name: { type: Type.STRING } } }
                                    },
                                    sources: { 
                                        type: Type.ARRAY, 
                                        items: { type: Type.OBJECT, properties: { uri: { type: Type.STRING }, title: { type: Type.STRING } } } 
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }) as GenerateContentResponse;

        const cleanedText = cleanJson(response.text || '{}');
        let result = JSON.parse(cleanedText);

        // Validation check to force retry if structure is bad
        if (!result || !Array.isArray(result.trends)) {
            throw new Error("Invalid JSON structure: Missing trends array");
        }

        result = verifySources(result, response);
        return result as ThreatLandscapeResult;
    }, 3, 2000); 
};

