    let markdown = `# Tailored Threat Landscape for ${audience}\n`;
    markdown += `**Generated for:** ${orgProfile}\n\n`;
    report.trends.forEach((trend, index) => {
        const tailored = trend.tailoredAnalyses?.find(a => a.audience === audience);
