// 2-Step Process to ensure quality and prevent truncation/JSON errors
export const generateThreatLandscape = async (orgProfile: string, period: { startDate: string, endDate: string, name: string }, numTrends: number) => {

    // Step 1: Identification (Lightweight)
    const identifyPrompt = `Identify the top ${numTrends} most critical cyber threat trends relevant to: ${orgProfile} for the period: ${period.name}.
    Return a simple JSON object: { "reportTitle": "string", "trendTitles": ["string", "string", ...] }`;

    const identityResponse = await retry(() => ai.models.generateContent({
        model: 'gemini-3-flash-preview', // Flash is sufficient for planning
        contents: identifyPrompt,
        config: {
            responseMimeType: 'application/json',
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    reportTitle: { type: Type.STRING },
                    trendTitles: { type: Type.ARRAY, items: { type: Type.STRING } }
                }
            }
        }
    })) as GenerateContentResponse;

    const identityData = JSON.parse(cleanJson(identityResponse.text || '{}'));
    if (!identityData.trendTitles || !Array.isArray(identityData.trendTitles)) {
        throw new Error("Failed to identify trends structure.");
    }

    // Step 2: Detailed Analysis (Parallel & Deep)
    // We run these in parallel to save time, but each is a focused Pro query with search
    const trendPromises = identityData.trendTitles.map(async (title: string) => {
        const detailPrompt = `Analyze the threat trend "${title}" specifically for ${orgProfile}.
        Structure the response as JSON:
        - globalImpact: A detailed paragraph (approx 50-80 words) summarizing the global state of this trend.
        - organizationalImpact: A detailed paragraph (approx 50-80 words) explaining why this matters to ${orgProfile} and potential consequences.
        - mitreTechniques: Up to 3 relevant MITRE ATT&CK techniques (id, name).

        Use Google Search to find recent evidence and examples.`;

        const response = await retry(() => ai.models.generateContent({
            model: 'gemini-3-pro-preview', // Pro for deep analysis
            contents: detailPrompt,
            config: {
                tools: [{ googleSearch: {} }],
                responseMimeType: 'application/json',
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        globalImpact: { type: Type.STRING },
                        organizationalImpact: { type: Type.STRING },
                        mitreTechniques: { 
                            type: Type.ARRAY,
                            items: { type: Type.OBJECT, properties: { id: { type: Type.STRING }, name: { type: Type.STRING } } }
                        }
                    }
                }
            }
        })) as GenerateContentResponse;

        // Manually extract sources since we aren't using the monolithic helper
        const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks
            ?.map((c: any) => ({ uri: c.web?.uri, title: c.web?.title }))
            .filter((s: any) => s.uri) || [];

        const details = JSON.parse(cleanJson(response.text || '{}'));

        return {
            trendTitle: title,
            globalImpact: details.globalImpact || "No data available.",
            organizationalImpact: details.organizationalImpact || "No data available.",
            mitreTechniques: details.mitreTechniques || [],
            sources: sources
        } as ThreatLandscapeTrend;
    });

    const detailedTrends = await Promise.all(trendPromises);

    return {
        reportTitle: identityData.reportTitle || "Threat Landscape Report",
        trends: detailedTrends
    } as ThreatLandscapeResult;
};

