const renderBulletedString = (text: string) => {
    if (!text || typeof text !== 'string') return <p className="text-text-secondary italic">No data available.</p>;

    // Split by common bullet delimiters or newlines
    const lines = text.split(/[\n•\-]+/).map(line => line.trim()).filter(line => line.length > 0);

    if (lines.length === 0) return <p className="text-text-secondary italic">No data available.</p>;

    // If it looks like a single paragraph (no obvious splits), render as text
    if (lines.length === 1 && text.length > 50 && !text.startsWith('-') && !text.startsWith('•')) {
         return <p>{text}</p>;
    }

    return (
        <ul className="list-none space-y-2">
            {lines.map((line, index) => (
                <li key={index} className="flex items-start">
                    <span className="mr-2 mt-1.5 h-1.5 w-1.5 rounded-full bg-accent-primary flex-shrink-0"></span>
                    <span className="leading-relaxed">{line}</span>
                </li>
            ))}
        </ul>
    );
};

