                        considerations: { type: Type.STRING },
                        assessment: { type: Type.STRING },
                    },
                    required: ["purpose", "situation", "considerations", "assessment"]
                }
            }
        });

        const data = JSON.parse(cleanJson(response.text || '{}'));
        return {
            purpose: data.purpose || "Purpose not specified.",
            situation: data.situation || "Situation not specified.",
            considerations: data.considerations || "No considerations provided.",
            assessment: data.assessment || "Assessment not available."
        } as Memorandum;
    });
};

